/* Œconomia — Entraînement : thème « Autres visions de l’économie » (18 exercices, trois niveaux).
   Polanyi, Kalecki, Aglietta, Waring, Kelton : encastrement, monnaie endogène, travail non rémunéré, mode de régulation. */
(function () {
  const X = OEC.exo, { rnd, pick, fmt } = X;
  const P = (...a) => a.map((t) => `<p>${t}</p>`).join("");

  X.theme({ id: "visions", nom: "Autres visions de l’économie",
    intro: "Le courant dominant n’est pas la seule manière de penser l’économie. Ces exercices vous font manipuler les idées des économistes hétérodoxes : l’économie encastrée dans la société, la monnaie créée par le crédit, le travail que le PIB ne compte pas, les institutions qui stabilisent le capitalisme.",
    notions: ["encastrement", "monnaie-endogene", "travail-non-remunere", "mode-regulation"] });

  X.add([
  /* =========================== NIVEAU 1 : DÉCOUVERTE =========================== */
  { id: "vi1-familles", theme: "visions", niveau: 1, type: "qcm", notion: "mode-regulation",
    titre: "Orthodoxe ou hétérodoxe ?", competence: "Situer un courant de pensée par rapport au courant dominant.",
    enonce: P("Laquelle de ces idées est défendue par un courant <b>hétérodoxe</b>, c’est-à-dire en marge du courant dominant ?"),
    options: ["Les individus comparent les coûts et les avantages avant de choisir.", "Un État qui émet sa propre monnaie ne peut pas faire faillite dans cette monnaie ; sa vraie limite est l’inflation.", "Un prix plafond inférieur au prix d’équilibre provoque une pénurie.", "Le commerce international repose sur l’avantage comparatif."], c: 1, pourquoi: ["Comparer coûts et avantages est le cœur du raisonnement du courant dominant.", null, "Le prix plafond et la pénurie font partie du modèle d’offre et de demande enseigné dans tous les manuels.", "L’avantage comparatif de Ricardo est enseigné par le courant dominant."],
    explication: P("C’est la thèse de la <b>théorie moderne de la monnaie</b>, portée par Stephanie Kelton, un courant post-keynésien hétérodoxe. Les trois autres idées sont enseignées dans tous les manuels.", "Voir la page <a href=\"#familles\">Les familles de pensée</a>.") },

  { id: "vi1-vf-polanyi", theme: "visions", niveau: 1, type: "vf", notion: "encastrement",
    titre: "Polanyi et le marché", competence: "Comprendre les notions d’encastrement et de marchandise fictive.", enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["Pour Polanyi, l’économie a longtemps été « encastrée » dans les relations sociales, religieuses et politiques.", true, "Pendant la plus grande partie de l’histoire, la parenté, la coutume ou le pouvoir réglaient la production et l’échange."],
      ["Le travail, la terre et la monnaie sont pour lui des « marchandises fictives ».", true, "Ils ne sont pas produits pour être vendus : le travail est la vie humaine, la terre est la nature, la monnaie une institution."],
      ["Polanyi soutient qu’il faut supprimer les marchés.", false, "Il ne rejette pas le marché, mais l’idée qu’il puisse régler seul toute la société."],
      ["Selon Polanyi, le marché autorégulateur du XIXe siècle est né spontanément, sans intervention de l’État.", false, "Au contraire : « le laissez-faire était planifié ». Il a fallu des lois pour créer un marché du travail et de la terre."]
    ] },

  { id: "vi1-pib", theme: "visions", niveau: 1, type: "qcm", notion: "travail-non-remunere",
    titre: "Ce que le PIB compte", competence: "Distinguer travail rémunéré et non rémunéré dans le PIB.",
    enonce: P("Laquelle de ces activités est comptée dans le PIB ?"),
    options: ["Un père prépare le repas de ses enfants.", "Une femme soigne sa mère âgée à domicile.", "Une aide ménagère payée nettoie un appartement.", "Un voisin répare bénévolement le vélo d’un enfant."], c: 2, pourquoi: ["Le repas est préparé gratuitement pour sa famille : ce travail n’entre pas dans le PIB.", "Les soins sont donnés sans paiement : ce travail non rémunéré n’est pas compté dans le PIB.", null, "La réparation est bénévole : sans paiement, rien n’entre dans le PIB."],
    explication: P("Le PIB compte la production vendue sur un marché ou fournie par les administrations, ainsi que quelques productions non vendues qu’on évalue par convention, comme le loyer que les propriétaires se versent en quelque sorte à eux-mêmes. Le travail domestique fait gratuitement pour sa famille ou ses voisins n’y figure pas. C’est le <b>travail non rémunéré</b>, mis en lumière par Marilyn Waring.", "Selon l’OFS, on y consacre en Suisse davantage d’heures qu’au travail payé.") },

  { id: "vi1-part-heures", theme: "visions", niveau: 1, type: "calcul", notion: "travail-non-remunere",
    titre: "La part du travail invisible", competence: "Calculer une part en pourcentage.",
    gen: () => { const u = rnd(90, 110) / 10, r = rnd(65, 85) / 10; return { u, r }; },
    enonce: (p) => P(`Dans un pays fictif, on consacre en une année <b>${fmt(p.u, 1)} milliards d’heures</b> au travail non rémunéré et <b>${fmt(p.r, 1)} milliards d’heures</b> au travail rémunéré.`, "Quelle part du travail total est non rémunérée ? Arrondissez à une décimale."),
    champs: [{ label: "Part non rémunérée", unite: "%", tol: 0.1 }],
    reponses: (p) => [Math.round((p.u / (p.u + p.r)) * 1000) / 10],
    indice: "Part = travail non rémunéré ÷ (travail non rémunéré + travail rémunéré) × 100.",
    correction: (p) => P(`Part = ${fmt(p.u, 1)} ÷ (${fmt(p.u, 1)} + ${fmt(p.r, 1)}) × 100`, `= ${fmt(p.u, 1)} ÷ ${fmt(p.u + p.r, 1)} × 100 ≈ <b>${fmt((p.u / (p.u + p.r)) * 100, 1)} %</b>.`, "Plus de la moitié du travail échappe au PIB. En Suisse, en 2020, l’OFS comptait 9,8 milliards d’heures non rémunérées contre environ 7,6 milliards rémunérées.") },

  { id: "vi1-pret", theme: "visions", niveau: 1, type: "qcm", notion: "monnaie-endogene",
    titre: "Un prêt crée-t-il de la monnaie ?", competence: "Comprendre la création monétaire par le crédit.",
    enonce: P("Une banque accorde à une entreprise un prêt de 50 000 francs, versé sur le compte de l’entreprise. Que devient la quantité de monnaie dans l’économie ?"),
    options: ["Elle ne change pas : la banque a seulement prêté l’argent de ses déposants.", "Elle augmente de 50 000 francs : la banque a créé un dépôt nouveau.", "Elle baisse de 50 000 francs, car la banque dispose de moins de réserves.", "Elle augmente, mais seulement quand l’entreprise aura dépensé la somme."], c: 1, pourquoi: ["C’est la présentation des anciens manuels. En pratique, la banque crédite le compte de l’entreprise sans retirer l’argent des autres déposants : elle crée de la monnaie.", null, "Le prêt ajoute un dépôt sur le compte de l’entreprise : la monnaie augmente. Elle baissera seulement au remboursement.", "Le dépôt existe dès que la banque crédite le compte. La monnaie est créée à cet instant, avant toute dépense."],
    explication: P("« Les crédits font les dépôts » : en accordant le prêt, la banque inscrit 50 000 francs sur le compte de l’entreprise. Cette monnaie n’existait pas auparavant. Elle disparaîtra quand le prêt sera remboursé.", "Voir la notice <a href=\"#c-monnaie-endogene\">Monnaie endogène</a>.") },

  { id: "vi1-vf-kalecki", theme: "visions", niveau: 1, type: "vf", notion: "mode-regulation",
    titre: "Kalecki et le plein emploi", competence: "Connaître les idées principales de Kalecki.", enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["Kalecki a publié une théorie proche de celle de la demande effective avant la Théorie générale de Keynes.", true, "Dès 1933, dans un essai en polonais. Joan Robinson et la plupart des post-keynésiens lui reconnaissent cette priorité. D’autres historiens, comme Don Patinkin, la contestent."],
      ["Pour Kalecki, l’État ne sait pas comment créer le plein emploi.", false, "Il pense que l’État sait le faire en dépensant, mais que les chefs d’entreprise s’y opposeront."],
      ["Selon lui, un plein emploi durable retire au licenciement son pouvoir de discipline.", true, "C’est l’argument central de son article de 1943."],
      ["Kalecki pense que les grandes entreprises fixent leurs prix en ajoutant une marge à leurs coûts.", true, "Cette marge dépend de leur pouvoir de marché, le « degré de monopole »."]
    ] },

  /* =========================== NIVEAU 2 : INTERMÉDIAIRE =========================== */
  { id: "vi2-remplacement", theme: "visions", niveau: 2, type: "calcul", notion: "travail-non-remunere",
    titre: "Donner une valeur au travail domestique", competence: "Estimer une valeur par la méthode du coût de remplacement.",
    gen: () => ({ h: rnd(14, 30), w: rnd(26, 36) }),
    enonce: (p) => P(`Une personne consacre <b>${p.h} heures par semaine</b> au ménage, aux repas et à la garde des enfants. Une aide à domicile serait payée <b>${p.w} francs de l’heure</b>.`, "Selon la méthode du coût de remplacement, quelle est la valeur annuelle de ce travail (52 semaines) ? Arrondissez au franc."),
    champs: [{ label: "Valeur annuelle", unite: "francs", tol: 1 }],
    reponses: (p) => [p.h * p.w * 52],
    indice: "Calculez d’abord la valeur d’une semaine, puis passez à l’année.",
    correction: (p) => P(`Valeur = ${p.h} × ${p.w} × 52`, `= <b>${fmt(p.h * p.w * 52)} francs</b> par an.`, "Ce travail ne figure dans aucun compte de revenus, ni dans le PIB. Les statisticiens l’estiment à part, dans des « comptes satellites ».") },

  { id: "vi2-profits", theme: "visions", niveau: 2, type: "calcul", notion: "mode-regulation",
    titre: "L’équation des profits de Kalecki", competence: "Appliquer une identité macroéconomique.",
    gen: () => ({ i: rnd(70, 120), c: rnd(30, 50), d: rnd(10, 40), x: rnd(-10, 25), s: rnd(5, 20) }),
    enonce: (p) => P("Dans la version élargie de Kalecki : profits = investissement + consommation des capitalistes + déficit public + excédent commercial − épargne des salariés.", `Dans un pays, en milliards : investissement <b>${p.i}</b>, consommation des capitalistes <b>${p.c}</b>, déficit public <b>${p.d}</b>, solde commercial <b>${p.x}</b>, épargne des salariés <b>${p.s}</b>.`, "Calculez les profits."),
    champs: [{ label: "Profits", unite: "milliards", tol: 0 }],
    reponses: (p) => [p.i + p.c + p.d + p.x - p.s],
    indice: "Additionnez les quatre premiers termes (le solde commercial peut être négatif), puis retirez l’épargne des salariés.",
    correction: (p) => P(`Profits = ${p.i} + ${p.c} + ${p.d} ${p.x < 0 ? "− " + -p.x : "+ " + p.x} − ${p.s}`, `= <b>${p.i + p.c + p.d + p.x - p.s} milliards</b>.`, "L’équation est une identité comptable, toujours vraie. Kalecki lui donne un sens causal. Les capitalistes peuvent décider de leurs dépenses, pas de leurs profits, ce sont donc les dépenses qui déterminent les profits. Toutes choses égales par ailleurs, un déficit public plus élevé augmente les profits, et l’épargne des salariés les réduit.") },

  { id: "vi2-fordisme", theme: "visions", niveau: 2, type: "qcm", notion: "mode-regulation",
    titre: "Le cercle du fordisme", competence: "Expliquer un enchaînement macroéconomique.",
    enonce: P("Quel enchaînement décrit le mieux le « fordisme » des Trente Glorieuses, selon l’école de la régulation ?"),
    options: ["Baisse des salaires → baisse des prix → hausse des exportations → croissance.", "Gains de productivité → hausse des salaires négociée → consommation de masse → investissement → nouveaux gains de productivité.", "Création monétaire → inflation → croissance.", "Hausse des impôts → baisse de la dette → croissance."], c: 1, pourquoi: ["Le fordisme repose sur la hausse des salaires, qui soutient la consommation, et non sur leur baisse.", null, "La croissance fordiste vient des gains de productivité partagés, pas de la création monétaire.", "Le fordisme est un régime de croissance fondé sur la consommation de masse, pas sur le désendettement."],
    explication: P("Les gains de productivité de la production de masse sont partagés avec les salariés par les conventions collectives. Les salariés achètent ce qu’ils produisent, ce qui soutient l’investissement. Le cercle se rompt à la fin des années 1960, quand la productivité ralentit.", "Voir la notice <a href=\"#c-mode-regulation\">Mode de régulation</a>.") },

  { id: "vi2-vf-monnaie", theme: "visions", niveau: 2, type: "vf", notion: "monnaie-endogene",
    titre: "Monnaie endogène", competence: "Distinguer deux explications de la création monétaire.", enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["Selon la thèse de la monnaie endogène, la banque centrale fixe directement la quantité de monnaie en circulation.", false, "Elle agit surtout par le taux d’intérêt ; la quantité de monnaie suit la demande de crédit."],
      ["Quand un prêt est remboursé, la monnaie correspondante disparaît.", true, "Le dépôt et la créance s’annulent ensemble."],
      ["Après 2008, la forte hausse des réserves bancaires n’a pas fait exploser la masse monétaire.", true, "Les banques prêtent selon la demande d’emprunteurs solvables, pas selon leurs réserves."],
      ["En 2018, les Suisses ont accepté de réserver la création monétaire à la BNS.", false, "L’initiative « Monnaie pleine » a été rejetée par environ 76 % des votants."]
    ] },

  { id: "vi2-kelton", theme: "visions", niveau: 2, type: "qcm", notion: "monnaie-endogene",
    titre: "La limite de la dépense publique", competence: "Comprendre la thèse de la théorie moderne de la monnaie.",
    enonce: P("Selon Stephanie Kelton, qu’est-ce qui limite vraiment les dépenses d’un État qui émet sa propre monnaie ?"),
    options: ["Le niveau de sa dette publique, qui finit par dépasser ce qu’il peut rembourser.", "La quantité d’or que détient sa banque centrale en réserve.", "L’inflation, quand la demande dépasse les ressources disponibles.", "Le budget voté l’année précédente, qui fixe un plafond de dépenses."], c: 2, pourquoi: ["Pour la théorie moderne de la monnaie, un État qui émet sa monnaie peut toujours payer sa dette dans cette monnaie : le niveau de la dette n’est pas la vraie limite.", "Les monnaies actuelles ne sont plus convertibles en or : les réserves d’or ne limitent pas la dépense.", null, "Le budget passé n’est pas une contrainte économique : seule compte la disponibilité des ressources réelles."],
    explication: P("Pour la théorie moderne de la monnaie, la question n’est pas « comment le payer ? », mais « avons-nous les ressources ? ». Ses critiques, comme Lawrence Summers, répondent qu’il est politiquement difficile d’augmenter les impôts à temps pour contenir l’inflation.", "Voir le duel <a href=\"#controverses\" data-debat=\"kelton-summers\">Kelton contre Summers</a>.") },

  { id: "vi2-red-pib", theme: "visions", niveau: 2, type: "redaction", notion: "travail-non-remunere",
    titre: "Faut-il compter le travail domestique dans le PIB ?", competence: "Argumenter sur un indicateur économique.",
    enonce: P("En Suisse, on consacre davantage d’heures au travail non rémunéré qu’au travail rémunéré, mais le PIB n’en compte aucune.", "<b>Consigne :</b> rappelez d’abord pourquoi ce travail n’est pas compté, présentez au moins deux arguments pour l’intégrer dans la mesure de la richesse, et au moins deux arguments contre, puis concluez. Longueur attendue, 10 à 15 lignes."),
    criteres: ["La réponse explique pourquoi le travail domestique n’est pas compté : il ne passe pas par un marché.", "Elle donne au moins deux arguments pour : invisibilité dans les politiques, égalité entre femmes et hommes, comparaisons faussées entre pays ou entre époques, retraites…", "Elle donne au moins deux arguments contre : difficulté de lui donner un prix, usage du PIB pour la conjoncture et les impôts, existence des comptes satellites…", "Elle se termine par une prise de position explicite (pour, contre ou à certaines conditions), justifiée par au moins un des arguments présentés."],
    corrige: P("Le PIB laisse de côté le travail fait gratuitement. Le travail domestique et de soin, assuré surtout par des femmes, en est donc absent, alors qu’il représente en Suisse plus d’heures que le travail rémunéré.", "<b>Pour l’intégrer</b>, on peut dire que ce qui n’est pas compté pèse moins dans les décisions : une coupe dans les crèches paraît faire des économies, alors qu’elle reporte du travail sur les familles. Le PIB fausse aussi les comparaisons : quand un service passe de la famille au marché, le PIB augmente sans que la production réelle change.", "<b>Contre</b>, on peut répondre que donner un prix à ce travail est difficile et que les résultats varient beaucoup selon la méthode ; et que le PIB sert surtout à suivre la conjoncture et les recettes fiscales, ce qu’un indicateur élargi brouillerait.", "<b>Conclusion :</b> la solution retenue par les statisticiens est de mesurer ce travail à côté du PIB, dans des comptes satellites, comme le fait l’OFS. Le débat porte sur la place que ces chiffres prennent dans les décisions publiques.") },

  /* =========================== NIVEAU 3 : AVANCÉ =========================== */
  { id: "vi3-creation", theme: "visions", niveau: 3, type: "calcul", notion: "monnaie-endogene",
    titre: "Création et destruction de monnaie", competence: "Calculer la variation des dépôts à partir des crédits accordés et remboursés.",
    gen: () => { const m = rnd(400, 700), n = rnd(60, 120); let r; do { r = rnd(40, 110); } while (r === n); return { m, n, r }; },
    enonce: (p) => P(`Les dépôts bancaires d’un pays s’élèvent à <b>${p.m} milliards</b> au début de l’année. Pendant l’année, les banques accordent <b>${p.n} milliards</b> de nouveaux crédits et reçoivent <b>${p.r} milliards</b> de remboursements.`, "En supposant que rien d’autre ne change, quel est le montant des dépôts à la fin de l’année, et de combien de pour cent ont-ils varié (une décimale, signe moins en cas de baisse) ?"),
    champs: [{ label: "Dépôts en fin d’année", unite: "milliards", tol: 0 }, { label: "Variation", unite: "%", tol: 0.1 }],
    reponses: (p) => [p.m + p.n - p.r, Math.round(((p.n - p.r) / p.m) * 1000) / 10],
    indice: "Les nouveaux crédits créent des dépôts, les remboursements en détruisent.",
    correction: (p) => P(`Dépôts en fin d’année = ${p.m} + ${p.n} − ${p.r} = <b>${p.m + p.n - p.r} milliards</b>.`, `Variation = (${p.n} − ${p.r}) ÷ ${p.m} × 100 ≈ <b>${fmt(((p.n - p.r) / p.m) * 100, 1)} %</b>.`, p.n === p.r ? "Les crédits nouveaux égalent les remboursements : la monnaie ne varie pas." : p.n > p.r ? "Les crédits nouveaux dépassent les remboursements : la monnaie augmente." : "Les remboursements dépassent les crédits nouveaux : la monnaie diminue, ce qui arrive quand l’économie se désendette.") },

  { id: "vi3-deux-methodes", theme: "visions", niveau: 3, type: "calcul", notion: "travail-non-remunere",
    titre: "Deux méthodes, deux valeurs", competence: "Calculer la valeur du travail domestique selon deux méthodes.",
    gen: () => ({ h: rnd(800, 1400), w: rnd(26, 34), W: rnd(40, 60) }),
    enonce: (p) => P(`Une ingénieure consacre <b>${fmt(p.h)} heures par an</b> au travail domestique. Une aide à domicile coûterait <b>${p.w} francs de l’heure</b> ; dans son métier, elle gagne <b>${p.W} francs de l’heure</b>.`, "Calculez la valeur de ce travail selon la méthode du coût de remplacement, puis selon celle du coût d’opportunité."),
    champs: [{ label: "Coût de remplacement", unite: "francs", tol: 1 }, { label: "Coût d’opportunité", unite: "francs", tol: 1 }],
    reponses: (p) => [p.h * p.w, p.h * p.W],
    indice: "Remplacement : ce que coûterait une personne payée pour le faire. Opportunité : ce qu’elle aurait gagné en travaillant pendant ce temps.",
    correction: (p) => P(`Coût de remplacement = ${fmt(p.h)} × ${p.w} = <b>${fmt(p.h * p.w)} francs</b>.`, `Coût d’opportunité = ${fmt(p.h)} × ${p.W} = <b>${fmt(p.h * p.W)} francs</b>.`, `La seconde méthode donne une valeur ${fmt((p.W / p.w), 1)} fois plus élevée : le choix de la méthode change beaucoup le résultat, c’est l’une des critiques adressées à ces estimations.`) },

  { id: "vi3-part-salaires", theme: "visions", niveau: 3, type: "calcul", notion: "mode-regulation",
    titre: "Productivité, salaires et partage", competence: "Relier productivité, salaire réel et part des salaires.",
    gen: () => { const q = pick([2, 2.5, 3, 3.5, 4]), w = pick([0.5, 1, 1.5, 2, 2.5, 3]); return { q, w }; },
    enonce: (p) => P(`Pendant une année, la productivité du travail augmente de <b>${fmt(p.q, 1)} %</b> et le salaire réel moyen de <b>${fmt(p.w, 1)} %</b>.`, "Comment évolue la part des salaires dans la valeur ajoutée ? Donnez la variation en pourcentage (deux décimales, signe moins s’il s’agit d’une baisse)."),
    champs: [{ label: "Variation de la part des salaires", unite: "%", tol: 0.02 }],
    reponses: (p) => [Math.round(((1 + p.w / 100) / (1 + p.q / 100) - 1) * 10000) / 100],
    indice: "La part des salaires évolue comme le rapport (1 + croissance du salaire réel) ÷ (1 + croissance de la productivité).",
    correction: (p) => { const v = ((1 + p.w / 100) / (1 + p.q / 100) - 1) * 100; return P(`Variation = (1 + ${fmt(p.w / 100, 3)}) ÷ (1 + ${fmt(p.q / 100, 3)}) − 1`, `≈ <b>${fmt(v, 2)} %</b>.`, "Quand les salaires réels progressent moins vite que la productivité, la part des salaires baisse. Sous le fordisme, les deux progressaient à peu près ensemble ; depuis les années 1980, la part des salaires a reculé dans de nombreux pays avancés."); } },

  { id: "vi3-vf-polanyi-hayek", theme: "visions", niveau: 3, type: "vf", notion: "encastrement",
    titre: "Polanyi contre Hayek", competence: "Distinguer deux visions opposées du marché.", enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["La Grande Transformation de Polanyi et La Route de la servitude de Hayek paraissent la même année.", true, "Toutes deux en 1944, écrites loin de Vienne, où leurs auteurs sont nés. Polanyi est en exil, Hayek enseigne à Londres depuis 1931."],
      ["Pour Hayek, la planification centrale de l’économie conduit à concentrer le pouvoir et menace les libertés politiques.", true, "C’est l’argument de « La Route de la servitude ». Hayek ne condamne pas toute intervention. Il admet par exemple un revenu minimum et des règles de concurrence."],
      ["Pour Polanyi, la crise des années 1930 vient d’un excès d’intervention publique.", false, "Pour lui, elle vient de l’utopie d’un marché autorégulateur, et de l’étalon-or qui exigeait de baisser les salaires."],
      ["Hayek défend que les prix transmettent une information dispersée qu’aucun planificateur ne peut rassembler.", true, "C’est l’idée de son article de 1945 sur l’utilisation de la connaissance."]
    ] },

  { id: "vi3-souverainete", theme: "visions", niveau: 3, type: "qcm", notion: "monnaie-endogene",
    titre: "Qui est souverain sur sa monnaie ?", competence: "Appliquer une notion à des cas concrets.",
    enonce: P("Selon la théorie moderne de la monnaie, lequel de ces États dispose de la plus grande marge pour dépenser sans risque de faillite ?"),
    options: ["La Grèce, qui utilise l’euro.", "Un pays émergent endetté en dollars américains.", "La Suisse, qui émet le franc, laisse flotter son change et s’endette en francs.", "Un pays dont la monnaie est fixée à l’or."], c: 2, pourquoi: ["La Grèce n’émet pas l’euro : elle peut manquer de monnaie pour rembourser, comme en 2010-2012.", "Un pays endetté en dollars doit gagner ou acheter des dollars pour rembourser : il peut faire faillite.", null, "Avec l’étalon-or, la création monétaire est limitée par le stock d’or : la marge de dépense est réduite."],
    explication: P("Un État souverain sur sa monnaie, avec un change flottant et une dette dans sa propre monnaie, ne peut pas être forcé à la faillite. La Grèce ne contrôle pas l’euro ; un pays endetté en dollars doit gagner des dollars ; l’étalon-or limite la création monétaire.", "La Suisse remplit ces conditions, mais elle s’impose un frein à l’endettement, accepté par 85 % des votants en 2001. Voir le portrait de <a href=\"#eco-kelton\">Stephanie Kelton</a>.") },

  { id: "vi3-red-frein", theme: "visions", niveau: 3, type: "redaction", notion: "monnaie-endogene",
    titre: "Le frein à l’endettement face à la théorie moderne de la monnaie", competence: "Confronter deux positions de politique économique.",
    enonce: P("Depuis 2003, la Confédération applique un frein à l’endettement : les dépenses doivent être couvertes par les recettes sur l’ensemble du cycle conjoncturel. Pour Stephanie Kelton, un État qui émet sa propre monnaie n’a pas besoin d’une telle règle.", "<b>Consigne :</b> présentez la position de Kelton et celle des défenseurs du frein, en utilisant au moins deux notions économiques. Faut-il, selon vous, assouplir le frein à l’endettement ? Longueur attendue, 15 à 25 lignes."),
    criteres: ["La réponse présente correctement la thèse de Kelton : souveraineté monétaire, pas de faillite dans sa propre monnaie, inflation comme vraie limite.", "Elle présente les arguments des défenseurs du frein : confiance dans le franc, expérience des déficits des années 1990, risque politique de trop dépenser, indépendance de la BNS.", "Elle mobilise au moins deux notions : inflation, dette publique, monnaie endogène, multiplicateur, taux d’intérêt…", "Elle se termine par une prise de position explicite (pour, contre ou à certaines conditions), justifiée par au moins un des arguments présentés."],
    corrige: P("Pour <b>Kelton</b>, la Suisse remplit toutes les conditions de la souveraineté monétaire : elle émet le franc, laisse flotter son change et s’endette en francs. Elle ne peut donc pas faire faillite, et sa vraie limite est l’inflation, très faible depuis des décennies. Le frein l’empêcherait d’investir davantage dans la transition énergétique ou la formation, alors que les ressources existent.", "Les <b>défenseurs du frein</b> répondent que la Suisse a connu des déficits durables dans les années 1990, que la confiance dans le franc repose aussi sur la rigueur budgétaire, et que les gouvernements ont tendance à dépenser volontiers et à augmenter les impôts trop tard. La BNS, indépendante, a pour mission la stabilité des prix, non le financement de l’État.", "<b>Avis :</b> on peut par exemple défendre un frein assoupli pour certains investissements publics, comme le proposent les partisans d’une « règle d’or », tout en conservant une discipline sur les dépenses courantes.") },
  { id: "vi1-fait-valeur", theme: "visions", niveau: 1, type: "vf", typeLib: "Constat ou jugement de valeur", etiquettes: ["Constat", "Jugement de valeur"],
    titre: "Constat ou jugement de valeur ?", competence: "Distinguer un constat, que l’on peut vérifier, d’un jugement de valeur, qui dit ce qui devrait être.",
    enonce: P("Pour chaque affirmation, dites s’il s’agit d’un <b>constat</b>, que l’on peut vérifier avec des données, même s’il se révèle faux, ou d’un <b>jugement de valeur</b>, qui dit ce qui devrait être."),
    affirmations: [
      ["Le travail domestique devrait être rémunéré.", false, "Il dit ce qui devrait être. Des faits peuvent éclairer le débat, mais pas le trancher : « devrait » signale un choix de société."],
      ["Une banque crée de la monnaie quand elle accorde un crédit.", true, "On peut le vérifier avec des données : c’est ainsi que les banques comptabilisent un prêt, comme l’expliquent les banques centrales elles-mêmes."],
      ["Selon l’OFS, on consacre en Suisse davantage d’heures au travail non rémunéré qu’au travail payé.", true, "On peut le vérifier avec des données : l’OFS publie un compte satellite du travail non rémunéré."],
      ["Les courants hétérodoxes méritent autant de place que le courant dominant dans les cours d’économie.", false, "Il dit ce qui devrait être. Des faits peuvent éclairer le débat, mais pas le trancher : la place à leur donner dépend de ce que l’on attend d’un cours."]] },
  ]);
  /* =========================== COMPLÉMENTS : séries portées à douze exercices (novembre 2026) =========================== */
  X.add([
  /* ----- Niveau 1 ----- */
  { id: "vi1-doc-temps", theme: "visions", niveau: 1, type: "document", notion: "travail-non-remunere",
    titre: "Le temps de travail d’un couple", competence: "Distinguer le travail rémunéré du travail non rémunéré dans un emploi du temps.",
    enonce: P("Un couple avec deux enfants note ses heures de travail pendant une semaine.") +
      `<table><thead><tr><th>Heures par semaine</th><th>Léa</th><th>Marc</th></tr></thead><tbody><tr><td>Emploi rémunéré</td><td>30</td><td>42</td></tr><tr><td>Tâches ménagères</td><td>18</td><td>8</td></tr><tr><td>Soins aux enfants</td><td>14</td><td>6</td></tr></tbody></table><p class="ex-source">Données inventées pour l’exercice.</p>` +
      P("Quelle lecture est correcte ?"),
    options: ["Léa travaille 6 heures de plus que Marc au total, et plus de la moitié de son travail n’est pas rémunérée.", "Marc travaille davantage que Léa, puisqu’il passe 12 heures de plus dans son emploi.", "Léa et Marc travaillent autant l’un que l’autre, car les écarts se compensent exactement.", "Les 46 heures de travail non rémunéré du couple sont comptées dans le PIB au salaire moyen."], c: 0,
    pourquoi: [null, "Marc a plus d’heures rémunérées, mais le travail ne se limite pas à l’emploi. En comptant le ménage et les enfants, Léa totalise 62 heures et Marc 56.", "Les écarts ne se compensent pas tout à fait. Léa fait 18 heures non rémunérées de plus que Marc, qui fait 12 heures rémunérées de plus qu’elle. Il reste 6 heures d’écart.", "Le PIB ne compte pas le travail domestique fait gratuitement pour sa propre famille. Ces 46 heures n’y figurent pas."],
    explication: P("Total de Léa : 30 + 18 + 14 = <b>62 heures</b>, dont 32 non rémunérées, soit 52 %. Total de Marc : 42 + 8 + 6 = <b>56 heures</b>, dont 14 non rémunérées, soit 25 %.", "Les statistiques de l’emploi ne voient que les 72 heures rémunérées du couple. Les 46 autres heures produisent pourtant des repas, du linge propre et des enfants gardés. L’économie féministe, avec Marilyn Waring, a montré que cet oubli fausse l’image de qui travaille et de ce qu’une société produit.") },

  { id: "vi1-graph-salaires", theme: "visions", niveau: 1, type: "graphique", notion: "mode-regulation",
    titre: "Salaires et productivité sur deux périodes", competence: "Comparer l’évolution de deux grandeurs sur un graphique en barres.",
    enonce: P("Le graphique compare deux périodes de vingt-cinq ans dans un pays industrialisé. Pour chacune, il donne le niveau atteint à la fin par la productivité du travail et par le salaire réel, en partant de 100 au début de la période.", "Que montre-t-il ?"),
    fig: () => X.barres({ cats: ["1950 à 1975", "1980 à 2005"], vals: [200, 160], vals2: [195, 115], noms: ["Productivité", "Salaire réel"], ymax: 235, dec: 0, aria: "Productivité et salaire réel à la fin de deux périodes, base 100 au début", caption: "Indices en fin de période (100 au début). Données inventées, d’un ordre de grandeur réaliste." }),
    options: ["Dans la seconde période, le salaire réel augmente beaucoup moins que la productivité.", "Dans la seconde période, le salaire réel baisse, puisque sa barre est plus basse qu’avant.", "Dans les deux périodes, le salaire réel et la productivité progressent du même pas.", "La productivité recule entre les deux périodes, puisqu’elle passe de 200 à 160."], c: 0,
    pourquoi: [null, "Un indice de 115 pour un départ à 100 signifie une hausse de 15 %. Le salaire réel augmente encore, mais lentement.", "C’est vrai de la première période seulement, où les deux indices atteignent 200 et 195. Dans la seconde, la productivité gagne 60 % et le salaire réel 15 %.", "Chaque période repart de 100. La productivité augmente de 100 % dans la première et de 60 % dans la seconde. Elle progresse moins vite, elle ne recule pas."],
    explication: P("De 1950 à 1975, la productivité double et le salaire réel aussi, ou presque. De 1980 à 2005, la productivité augmente de <b>60 %</b> et le salaire réel de <b>15 %</b> seulement.", "L’école de la régulation appelle <b>fordisme</b> le régime de la première période. Les gains de productivité y sont partagés avec les salariés, dont la consommation fait vivre la production de masse. Dans la seconde période, ce lien se défait, et la part des profits augmente.") },

  { id: "vi1-veblen", theme: "visions", niveau: 1, type: "qcm", notion: "consommation-ostentatoire",
    titre: "Quand un prix élevé attire les acheteurs", competence: "Reconnaître une consommation ostentatoire.",
    enonce: P("Une marque de montres de luxe double ses prix sans rien changer à ses modèles. L’année suivante, ses ventes augmentent.", "Comment Thorstein Veblen expliquerait-il ce résultat ?"),
    options: ["Une partie des acheteurs recherche le prix élevé lui-même, parce qu’il montre aux autres leur rang social.", "Les acheteurs sont mal informés et prennent à tort un prix élevé pour un signe de meilleure qualité.", "Le coût de fabrication des montres a doublé, et les acheteurs acceptent de le payer.", "Les acheteurs prévoient de nouvelles hausses et achètent pour revendre plus cher."], c: 0,
    pourquoi: [null, "Les modèles n’ont pas changé, et ces acheteurs le savent. Ce qu’ils achètent n’est pas une qualité supposée, mais le fait d’être vus avec un objet que peu de gens peuvent s’offrir.", "L’énoncé ne dit rien d’une hausse des coûts. Et un coût plus élevé expliquerait le prix, pas le fait que les ventes augmentent.", "Ce serait une spéculation, qui porte sur la revente. Veblen décrit autre chose, un objet qu’on garde et qu’on montre."],
    explication: P("Veblen appelle <b>consommation ostentatoire</b> les dépenses faites pour être vues. L’objet vaut par ce qu’il dit de son propriétaire. Un prix plus élevé le rend plus désirable, puisqu’il le réserve à moins de monde.", "Ces biens échappent à la loi habituelle de la demande. Pour Veblen, les goûts ne sont pas donnés une fois pour toutes. Ils se forment par comparaison avec les autres, ce que l’analyse courante du consommateur laisse de côté.") },

  { id: "vi1-surtravail", theme: "visions", niveau: 1, type: "calcul", notion: "plus-value",
    titre: "Travail nécessaire et surtravail", competence: "Calculer le surtravail d’une journée dans le raisonnement de Marx.",
    gen: () => { const h = pick([8, 9, 10]), v = pick([40, 50, 60]), n = pick([4, 5, 6]); return { h, v, w: n * v, n }; },
    enonce: (p) => P(`Dans un atelier, un ouvrier travaille <b>${p.h} heures</b> par jour. Chaque heure de son travail ajoute <b>${p.v} francs</b> de valeur aux produits. Son salaire est de <b>${p.w} francs</b> par jour.`, "Pour Marx, une partie de la journée sert à produire l’équivalent du salaire, et le reste est du surtravail. Combien d’heures de surtravail la journée compte-t-elle ?"),
    champs: [{ label: "Surtravail", unite: "heures", tol: 0.05 }],
    reponses: (p) => [p.h - p.n],
    indice: "Cherchez d’abord en combien d’heures l’ouvrier produit une valeur égale à son salaire.",
    correction: (p) => P(`Travail nécessaire : ${p.w} ÷ ${p.v} = ${p.n} heures. En ${p.n} heures, l’ouvrier a produit la valeur de son salaire.`, `Surtravail = ${p.h} − ${p.n} = <b>${p.h - p.n} heures</b>.`, `Pendant ces ${p.h - p.n} heures, il crée ${(p.h - p.n) * p.v} francs de valeur qui reviennent à l’employeur. Marx appelle cette somme la <b>plus-value</b> et y voit l’origine du profit. Les économistes néoclassiques expliquent le profit autrement, comme la rémunération du capital avancé et du risque pris.`) },

  { id: "vi1-hayek", theme: "visions", niveau: 1, type: "qcm",
    titre: "Ce que les prix savent", competence: "Expliquer le rôle des prix chez Hayek.",
    enonce: P("Dans une économie planifiée, un bureau central fixe les prix et les quantités de milliers de produits. Friedrich Hayek soutient qu’il ne peut pas y parvenir aussi bien qu’un marché.", "Quel est son argument ?"),
    options: ["Les connaissances utiles sont dispersées entre des millions de personnes, et les prix les résument.", "Les fonctionnaires d’un bureau central sont moins compétents que les dirigeants des entreprises.", "Les moyens de calcul sont insuffisants pour traiter autant de produits à la fois.", "Les prix du marché reflètent la valeur véritable des biens, alors que ceux d’un bureau sont arbitraires."], c: 0,
    pourquoi: [null, "L’argument ne porte pas sur la compétence des personnes. Même le meilleur planificateur ne disposerait pas des informations locales que chacun garde pour soi.", "Le problème n’est pas la puissance de calcul. Les données à calculer n’existent nulle part sous une forme qu’on puisse rassembler, car elles changent sans cesse et beaucoup ne sont connues que de ceux qui agissent.", "Hayek ne dit pas que les prix sont justes. Il dit qu’ils transmettent une information, sans porter de jugement sur la répartition qui en résulte."],
    explication: P("Pour Hayek, chacun détient des connaissances que personne d’autre n’a, comme l’état de son stock, les besoins de ses clients ou une occasion locale. Aucun bureau ne peut les réunir.", "Le <b>prix</b> les résume. Quand l’étain devient rare, son prix monte, et des milliers d’utilisateurs l’économisent sans avoir besoin de savoir pourquoi. Le marché est un moyen de coordonner des savoirs dispersés.", "Cet argument, formulé en 1945, a pesé dans le débat sur la planification. Ses critiques rappellent que les prix ne tiennent pas compte de ce qui n’a pas de marché, comme la pollution, ni des besoins de ceux qui n’ont pas de revenu.") },

  /* ----- Niveau 2 ----- */
  { id: "vi2-plus-value", theme: "visions", niveau: 2, type: "calcul", notion: "plus-value",
    titre: "Taux de plus-value et taux de profit", competence: "Calculer les grandeurs de base de l’analyse de Marx à partir d’une production.",
    gen: () => { const c = rnd(4, 9) * 100, v = rnd(2, 5) * 100, e = pick([50, 80, 100, 150]); return { c, v, w: c + v + v * e / 100 }; },
    enonce: (p) => P(`En une semaine, une fabrique utilise pour <b>${fmt(p.c)} francs</b> de machines et de matières (capital constant) et verse <b>${fmt(p.v)} francs</b> de salaires (capital variable). La valeur des marchandises produites est de <b>${fmt(p.w)} francs</b>.`, "Calculez le taux de plus-value (plus-value rapportée aux salaires), le taux de profit (plus-value rapportée à tout le capital avancé, une décimale) et la composition organique du capital (capital constant divisé par capital variable, deux décimales)."),
    champs: [{ label: "Taux de plus-value", unite: "%", tol: 0.1 }, { label: "Taux de profit", unite: "%", tol: 0.1 }, { label: "Composition organique", unite: "", tol: 0.01 }],
    reponses: (p) => { const pl = p.w - p.c - p.v; return [Math.round(pl / p.v * 1000) / 10, Math.round(pl / (p.c + p.v) * 1000) / 10, Math.round(p.c / p.v * 100) / 100]; },
    indice: "La plus-value est ce qui reste de la valeur produite une fois retirés le capital constant et les salaires.",
    correction: (p) => { const pl = p.w - p.c - p.v; return P(`Plus-value = ${fmt(p.w)} − ${fmt(p.c)} − ${fmt(p.v)} = ${fmt(pl)} francs.`, `Taux de plus-value = ${fmt(pl)} ÷ ${fmt(p.v)} = <b>${fmt(pl / p.v * 100, 1)} %</b>.`, `Taux de profit = ${fmt(pl)} ÷ (${fmt(p.c)} + ${fmt(p.v)}) ≈ <b>${fmt(pl / (p.c + p.v) * 100, 1)} %</b>.`, `Composition organique = ${fmt(p.c)} ÷ ${fmt(p.v)} ≈ <b>${fmt(p.c / p.v, 2)}</b>.`, "Chez Marx, seul le travail crée de la valeur nouvelle. À taux de plus-value donné, plus une entreprise remplace des salariés par des machines, plus sa composition organique monte et plus son taux de profit baisse. Il en tire une loi de baisse tendancielle du taux de profit. Une critique célèbre, formulée par Nobuo Okishio en 1961, observe qu’une entreprise n’adopte une technique que si elle abaisse ses coûts. À salaire réel constant, une telle technique ne peut pas faire baisser le taux de profit général."); } },

  { id: "vi2-graph-kuznets-env", theme: "visions", niveau: 2, type: "graphique",
    titre: "La croissance finit-elle par réduire la pollution ?", competence: "Lire une courbe en cloche et en discuter la portée.",
    enonce: P("Selon la « courbe de Kuznets environnementale », la pollution augmente quand un pays s’enrichit, puis diminue au-delà d’un certain revenu. Le graphique en donne la forme.", "Quelle objection les économistes de l’écologie adressent-ils à cette courbe ?"),
    fig: () => X.graphe({ xmax: 43, ymax: 118, ylab: "Pollution par habitant", xlab: "Revenu par habitant (milliers de $)", aria: "Courbe en cloche : la pollution par habitant augmente puis diminue avec le revenu",
      gx: [[10, "10"], [20, "20"], [30, "30"], [40, "40"]],
      lignes: [{ f: (x) => 0.25 * x * (40 - x), de: 0, a: 40, col: "d" }],
      points: [{ x: 20, y: 100, lab: "sommet", dx: 10, dy: -8 }],
      caption: "Courbe théorique." }),
    options: ["Elle vaut pour des pollutions locales, mais pas pour le CO2, et elle néglige les émissions importées.", "Elle montre que la croissance suffit à régler les problèmes d’environnement, ce qui rend inutile une politique environnementale.", "Elle prouve que les pays pauvres polluent davantage par habitant que les pays riches.", "Elle suppose que la population d’un pays diminue quand son revenu par habitant augmente."], c: 0,
    pourquoi: [null, "C’est la lecture optimiste de la courbe, et non une objection. Elle est justement ce que contestent les économistes de l’écologie.", "La courbe dit l’inverse pour les pays les plus pauvres, qui se trouvent tout à gauche, avec une pollution faible. Le maximum est atteint à un revenu intermédiaire.", "La courbe porte sur la pollution par habitant et ne fait aucune hypothèse sur la population."],
    explication: P("La courbe a été observée pour des polluants <b>locaux</b>, comme le dioxyde de soufre ou les particules, dont les habitants subissent directement les effets et qu’ils finissent par faire réglementer.", "Elle se vérifie mal pour le <b>CO2</b>, dont les dommages sont mondiaux et différés. Elle néglige aussi les <b>émissions importées</b>. Un pays riche peut réduire la pollution de son territoire en achetant à l’étranger les biens dont la fabrication pollue.", "Pour Herman Daly et les économistes de l’écologie, l’économie est un sous-système d’une planète finie, et la taille de l’économie compte autant que sa propreté. Les économistes de l’environnement d’inspiration néoclassique répondent qu’un prix du carbone suffisant peut découpler la production et les émissions.") },

  { id: "vi2-doc-decouplage", theme: "visions", niveau: 2, type: "document",
    titre: "Découplage relatif ou absolu ?", competence: "Distinguer un découplage relatif d’un découplage absolu dans un tableau.",
    enonce: P("Le tableau donne l’évolution de quatre indicateurs d’un pays entre 2000 et 2020.") +
      `<table><thead><tr><th>Indicateur</th><th>Variation de 2000 à 2020</th></tr></thead><tbody><tr><td>PIB réel</td><td>+40 %</td></tr><tr><td>Émissions de gaz à effet de serre sur le territoire</td><td>−15 %</td></tr><tr><td>Empreinte carbone (émissions liées aux importations comprises)</td><td>+5 %</td></tr><tr><td>Consommation de matières premières</td><td>+20 %</td></tr></tbody></table><p class="ex-source">Données inventées pour l’exercice.</p>` +
      P("Quelle lecture est correcte ?"),
    options: ["Le découplage est absolu pour les émissions du territoire, et relatif pour l’empreinte carbone et les matières.", "Le découplage est absolu pour les trois indicateurs, puisque chacun progresse moins vite que le PIB.", "Il n’y a aucun découplage, puisque le PIB a augmenté pendant toute la période.", "Le découplage est relatif pour les émissions du territoire, qui augmentent moins vite que le PIB."], c: 0,
    pourquoi: [null, "Progresser moins vite que le PIB définit un découplage relatif. Il n’est absolu que si l’indicateur baisse, ce qui n’est le cas ni de l’empreinte (+5 %) ni des matières (+20 %).", "Le découplage ne demande pas que le PIB stagne. Il compare l’évolution du PIB à celle des pressions sur l’environnement, et celles-ci évoluent toutes moins vite que lui.", "Les émissions du territoire ne ralentissent pas, elles baissent de 15 %. C’est un découplage absolu."],
    explication: P("Il y a <b>découplage relatif</b> quand une pression sur l’environnement augmente moins vite que le PIB, et <b>découplage absolu</b> quand elle diminue alors que le PIB augmente.", "Les émissions du territoire baissent (−15 %), ce qui donne un découplage absolu. L’empreinte carbone (+5 %) et les matières (+20 %) augmentent moins que le PIB (+40 %), ce qui donne un découplage relatif seulement.", "L’écart entre les émissions du territoire et l’empreinte carbone vient des importations. Une partie des émissions a été déplacée vers les pays qui fabriquent les biens consommés ici. Les partisans de la croissance verte y voient un progrès à amplifier. Ceux de la décroissance répondent que seul un découplage absolu, rapide et mesuré sur l’empreinte, serait à la hauteur des objectifs climatiques.") },

  { id: "vi2-prix-marge", theme: "visions", niveau: 2, type: "calcul",
    titre: "Fixer un prix par la marge", competence: "Calculer un prix à partir d’un coût et d’un taux de marge, et distinguer marge sur le coût et marge sur le prix.",
    gen: () => ({ cout: rnd(4, 12) * 10, m: pick([25, 50, 60, 100]) }),
    enonce: (p) => P(`Pour Michał Kalecki, la plupart des entreprises industrielles ne subissent pas un prix de marché. Elles fixent leur prix en ajoutant une marge à leur coût. Une entreprise produit un article qui lui coûte <b>${p.cout} francs</b> et applique une marge de <b>${p.m} %</b> sur ce coût.`, "Calculez son prix de vente, puis la part de la marge dans ce prix (en %, une décimale)."),
    champs: [{ label: "Prix de vente", unite: "fr.", tol: 0.01 }, { label: "Marge en % du prix", unite: "%", tol: 0.1 }],
    reponses: (p) => [p.cout * (1 + p.m / 100), Math.round(p.m / (100 + p.m) * 1000) / 10],
    indice: "La marge en francs est la même dans les deux calculs. Seule change la grandeur à laquelle on la rapporte, le coût ou le prix.",
    correction: (p) => { const prix = p.cout * (1 + p.m / 100); return P(`Marge en francs : ${p.cout} × ${p.m} ÷ 100 = ${fmt(prix - p.cout)} francs.`, `Prix de vente = ${p.cout} + ${fmt(prix - p.cout)} = <b>${fmt(prix)} francs</b>.`, `Marge en % du prix = ${fmt(prix - p.cout)} ÷ ${fmt(prix)} × 100 ≈ <b>${fmt(p.m / (100 + p.m) * 100, 1)} %</b>.`, `Une marge de ${p.m} % sur le coût ne représente que ${fmt(p.m / (100 + p.m) * 100, 1)} % du prix. Confondre les deux taux est une erreur fréquente en gestion.`, "Pour Kalecki, le niveau de la marge reflète le pouvoir de marché de l’entreprise, qu’il appelle le degré de monopole. Il détermine aussi le partage du revenu. Plus les marges sont élevées, plus la part des profits est grande et celle des salaires petite."); } },

  { id: "vi2-vf-comportement", theme: "visions", niveau: 2, type: "vf", notion: "aversion-pertes",
    titre: "Des décisions moins rationnelles que prévu", competence: "Appliquer les résultats de l’économie comportementale à des situations courantes.",
    enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["Afficher d’abord un prix élevé, puis un rabais, ne change pas ce que les clients sont prêts à payer.", false, "Le premier prix sert de point de repère. Les clients jugent le second par rapport à lui et acceptent de payer davantage. C’est l’effet d’ancrage."],
      ["Perdre 100 francs fait en général plus de peine que gagner 100 francs ne fait plaisir.", true, "C’est l’aversion aux pertes, mise en évidence par Daniel Kahneman et Amos Tversky. Une perte pèse environ deux fois plus qu’un gain de même montant."],
      ["Inscrire d’office les salariés à un plan d’épargne, en les laissant libres d’en sortir, augmente nettement le nombre d’épargnants.", true, "La plupart des gens gardent l’option proposée par défaut. Richard Thaler en a tiré l’idée du coup de pouce, qui oriente les choix sans rien interdire."],
      ["Pour l’économie comportementale, les erreurs de jugement se compensent d’une personne à l’autre et n’ont donc pas d’effet d’ensemble.", false, "Elle montre au contraire que ces erreurs vont dans le même sens chez la plupart des gens. Elles ne s’annulent pas et peuvent peser sur les prix et sur l’épargne."]
    ] },

  { id: "vi2-transaction", theme: "visions", niveau: 2, type: "qcm",
    titre: "Faire ou faire faire ?", competence: "Appliquer la notion de coût de transaction au choix entre le marché et l’entreprise.",
    enonce: P("Un fabricant de machines hésite entre produire lui-même une pièce très spécifique et la commander à un fournisseur.", "Que prévoit la théorie des coûts de transaction de Ronald Coase et d’Oliver Williamson ?"),
    options: ["Il la produit lui-même si passer par un fournisseur coûte plus cher que l’organiser en interne.", "Il la commande, parce que la concurrence entre fournisseurs donne le prix le plus bas.", "Il compare son coût de fabrication au prix du fournisseur et retient le plus bas des deux.", "Il la produit lui-même, parce qu’une grande entreprise a des coûts plus faibles."], c: 0,
    pourquoi: [null, "Pour une pièce très spécifique, les fournisseurs sont rares. Une fois le contrat signé, chacun dépend de l’autre, et la concurrence ne joue plus.", "Cette comparaison oublie ce que coûte le recours au marché lui-même. Il faut chercher un fournisseur, négocier, rédiger un contrat, vérifier la qualité et gérer les litiges.", "La taille ne garantit rien. Diriger une organisation a aussi un coût, qui augmente avec sa taille. C’est ce qui limite la croissance des entreprises."],
    explication: P("Passer par le marché a un coût, celui de chercher un partenaire, de négocier, de rédiger un contrat et d’en surveiller l’exécution. Ce sont les <b>coûts de transaction</b>. Ronald Coase y voit dès 1937 la raison d’être de l’entreprise, qui remplace des contrats répétés par une organisation.", "Oliver Williamson précise quand ces coûts sont élevés. C’est le cas d’un actif <b>spécifique</b>, qui n’a de valeur que pour un seul client. Le fournisseur qui a investi pour lui devient dépendant, et chacun peut chercher à renégocier. Produire en interne évite ce risque.", "Cette approche institutionnaliste explique des faits que le modèle de marché laisse de côté, comme la taille des entreprises, l’intégration verticale ou les contrats de longue durée.") },

  /* ----- Niveau 3 ----- */
  { id: "vi3-kalecki", theme: "visions", niveau: 3, type: "calcul", notion: "demande-effective",
    titre: "Marges, profits et revenu chez Kalecki", competence: "Résoudre un petit modèle de répartition et de demande et en tirer une statique comparative.",
    gen: () => { const mu = pick([25, 50, 100]); return { mu, mu2: mu === 25 ? 50 : mu === 50 ? 100 : 150, sp: pick([0.4, 0.5, 0.8]), I: pick([60, 80, 100, 120]) }; },
    enonce: (p) => P(`Dans une économie fermée et sans État, les entreprises fixent leurs prix en ajoutant une marge de <b>${p.mu} %</b> au coût salarial. Les salariés consomment tout leur revenu. Les détenteurs de profits en épargnent une part de <b>${fmt(p.sp)}</b>. L’investissement, décidé à l’avance, vaut <b>${p.I} milliards</b>.`, `Calculez la part des profits dans le revenu (en %, une décimale), le montant des profits, puis le revenu national. Calculez enfin le revenu national si la marge passe à <b>${p.mu2} %</b>, l’investissement restant le même. Arrondissez les résultats à une décimale, mais gardez la part des profits sous forme de fraction exacte dans vos calculs.`),
    champs: [{ label: "Part des profits", unite: "%", tol: 0.1 }, { label: "Profits", unite: "milliards", tol: 0.1 }, { label: "Revenu national", unite: "milliards", tol: 1 }, { label: "Revenu avec la nouvelle marge", unite: "milliards", tol: 1 }],
    reponses: (p) => { const pi = p.mu / (100 + p.mu), pi2 = p.mu2 / (100 + p.mu2), Pr = p.I / p.sp; return [Math.round(pi * 1000) / 10, Math.round(Pr * 10) / 10, Math.round(Pr / pi * 10) / 10, Math.round(Pr / pi2 * 10) / 10]; },
    indice: "Si le prix vaut (1 + marge) fois le coût salarial, la part des salaires dans le revenu est 1 ÷ (1 + marge). Pour les profits, écrivez que l’épargne est égale à l’investissement.",
    correction: (p) => { const pi = p.mu / (100 + p.mu), pi2 = p.mu2 / (100 + p.mu2), Pr = p.I / p.sp; return P(`Part des salaires = 1 ÷ ${fmt(1 + p.mu / 100)}, donc part des profits = ${p.mu} ÷ ${100 + p.mu}.`, `Soit une part des profits de <b>${fmt(pi * 100, 1)} %</b>.`, `Seuls les profits sont épargnés. L’égalité de l’épargne et de l’investissement s’écrit ${fmt(p.sp)} × profits = ${p.I}, donc profits = <b>${fmt(Pr, 1)} milliards</b>.`, `Revenu national = profits ÷ part des profits = ${fmt(Pr, 1)} ÷ ${fmt(pi, 4)} ≈ <b>${fmt(Pr / pi, 1)} milliards</b>.`, `Avec une marge de ${p.mu2} %, la part des profits monte à ${fmt(pi2 * 100, 1)} %. Les profits restent de ${fmt(Pr, 1)} milliards, puisque l’investissement n’a pas changé, et le revenu tombe à <b>${fmt(Pr / pi2, 1)} milliards</b>.`, "Des marges plus élevées n’augmentent pas les profits. Elles réduisent les salaires, donc la consommation et la production. Kalecki résume l’idée ainsi : les salariés dépensent ce qu’ils gagnent, les capitalistes gagnent ce qu’ils dépensent.", "Le résultat suppose un investissement donné. Les économistes néoclassiques objectent que des profits plus élevés stimulent l’investissement. Amit Bhaduri et Stephen Marglin ont montré qu’une économie peut être tirée par les salaires ou par les profits selon la force de cette réaction."); } },

  { id: "vi3-soldes", theme: "visions", niveau: 3, type: "calcul", notion: "monnaie-endogene",
    titre: "Les trois soldes financiers", competence: "Utiliser l’identité des soldes sectoriels pour raisonner sur un déficit public.",
    gen: () => ({ d: pick([2, 4, 5, 6]), ca: pick([-3, -1, 2, 4, 6]) }),
    enonce: (p) => P(`Dans un pays, le déficit public est de <b>${p.d} % du PIB</b> et le solde des transactions courantes de <b>${p.ca > 0 ? "+" : ""}${p.ca} % du PIB</b>. Les soldes financiers du secteur privé, du secteur public et du reste du monde s’annulent : solde privé + solde public = solde courant.`, "Calculez le solde financier du secteur privé (ménages et entreprises ensemble). Le gouvernement décide ensuite de ramener son déficit à zéro. Que devient le solde privé si le solde courant ne change pas ? Indiquez un signe moins pour un solde négatif."),
    champs: [{ label: "Solde privé", unite: "% du PIB", tol: 0.05 }, { label: "Solde privé après l’équilibre du budget", unite: "% du PIB", tol: 0.05 }],
    reponses: (p) => [p.ca + p.d, p.ca],
    indice: "Un déficit public est un solde public négatif. Isolez le solde privé dans l’identité.",
    correction: (p) => P(`Solde public = −${p.d}. L’identité donne solde privé = solde courant − solde public = ${p.ca} − (−${p.d}).`, `Soit un solde privé de <b>${p.ca + p.d} % du PIB</b>.`, `Avec un budget à l’équilibre, solde privé = ${p.ca} − 0 = <b>${p.ca} % du PIB</b>.`, p.ca < 0 ? "Le secteur privé devrait alors dépenser plus qu’il ne gagne, donc s’endetter, tant que le pays reste en déficit courant. Si les ménages et les entreprises ne le veulent pas, ils réduisent leurs dépenses, et c’est le revenu national qui s’ajuste à la baisse." : `L’épargne nette du secteur privé devrait passer de ${p.ca + p.d} % à ${p.ca} % du PIB. Si les ménages et les entreprises veulent continuer d’épargner autant, ils réduisent leurs dépenses, et le revenu national baisse jusqu’à ce que les soldes redeviennent compatibles.`, "L’identité est comptable et toujours vraie. Elle ne dit pas quel solde s’ajuste ni par quel chemin. Wynne Godley et les post-keynésiens en tirent qu’un État ne choisit pas seul son solde et qu’une austérité menée quand le secteur privé veut épargner déprime l’activité. Les économistes néoclassiques répondent que les taux d’intérêt et le taux de change rééquilibrent les soldes sans perte durable de production.") },

  { id: "vi3-graph-regimes", theme: "visions", niveau: 3, type: "graphique", notion: "demande-effective",
    titre: "Croissance tirée par les salaires ou par les profits", competence: "Interpréter un graphique reliant le partage du revenu et la croissance.",
    enonce: P("Le graphique relie la part des salaires dans le revenu et le taux de croissance pour deux économies types, A et B.", "Dans une économie de type A, que produit une baisse de la part des salaires ?"),
    fig: () => X.graphe({ xmin: 50, xmax: 80, ymax: 4.4, ylab: "Croissance (%)", xlab: "Part des salaires (%)", aria: "Deux droites : la croissance augmente avec la part des salaires dans l’économie A et diminue dans l’économie B",
      gx: [[55, "55"], [65, "65"], [75, "75"]], gy: [[1, "1"], [2, "2"], [3, "3"]],
      lignes: [{ pts: [[55, 1], [75, 3]], col: "d", lab: "économie A", at: [75, 3], dx: 4, dy: -10, anc: "end" }, { pts: [[55, 3], [75, 1]], col: "o", lab: "économie B", at: [75, 1], dx: 4, dy: 22, anc: "end" }],
      caption: "Schéma construit pour l’exercice, d’après le modèle d’Amit Bhaduri et de Stephen Marglin (1990)." }),
    options: ["Un ralentissement, car la baisse de la consommation pèse plus que le gain d’investissement.", "Une accélération, car des profits plus élevés permettent aux entreprises d’investir davantage.", "Un effet négligeable, car le partage du revenu pèse peu sur la demande globale.", "Une accélération, comme dans l’économie B, mais d’une ampleur plus faible."], c: 0,
    pourquoi: [null, "C’est ce qui se passe dans l’économie B. Dans l’économie A, la droite monte, donc moins de salaires veut dire moins de croissance.", "Les deux droites ont une pente. Dans les deux économies, le partage du revenu modifie la croissance, mais en sens opposés.", "Les droites ont des pentes de signe contraire. Une baisse de la part des salaires accélère la croissance en B et la ralentit en A."],
    explication: P("Une baisse de la part des salaires a deux effets opposés. Elle réduit la <b>consommation</b>, puisque les salariés dépensent une plus grande part de leur revenu que les détenteurs de profits. Elle peut stimuler l’<b>investissement</b>, par des profits plus élevés, et les <b>exportations</b>, par des coûts plus bas.", "Dans l’économie A, le premier effet domine, le régime est <b>tiré par les salaires</b>, et la modération salariale freine la croissance. Dans l’économie B, c’est l’inverse, le régime est <b>tiré par les profits</b>.", "Les études post-keynésiennes concluent en général que les grandes économies peu ouvertes sont tirées par les salaires, et que de petits pays très ouverts peuvent être tirés par les profits. Si tous modèrent leurs salaires en même temps, le gain de compétitivité s’annule et il ne reste que la perte de demande. Les économistes néoclassiques contestent ce cadre, où la croissance de long terme dépend de la demande et non de l’offre.") },

  { id: "vi3-doc-regulation", theme: "visions", niveau: 3, type: "document", notion: "mode-regulation",
    titre: "Reconnaître deux régimes de croissance", competence: "Analyser un tableau avec les notions de l’école de la régulation.",
    enonce: P("Le tableau résume deux périodes de l’histoire économique d’un pays industrialisé.") +
      `<table><thead><tr><th>Indicateur</th><th>Période 1</th><th>Période 2</th></tr></thead><tbody><tr><td>Productivité du travail, par an</td><td>+4,0 %</td><td>+1,5 %</td></tr><tr><td>Salaire réel, par an</td><td>+3,8 %</td><td>+0,6 %</td></tr><tr><td>Salariés couverts par une convention collective</td><td>80 %</td><td>45 %</td></tr><tr><td>Part des profits versée aux actionnaires</td><td>30 %</td><td>55 %</td></tr><tr><td>Dette des ménages, en % de leur revenu</td><td>40 %</td><td>110 %</td></tr></tbody></table><p class="ex-source">Valeurs stylisées, construites pour l’exercice.</p>` +
      P("Quelle lecture propose l’école de la régulation ?"),
    options: ["En période 1, les salaires suivent la productivité et soutiennent la demande. En période 2, ce lien se rompt et le crédit prend le relais.", "En période 2, la baisse des conventions collectives libère les entreprises, ce qui accélère la productivité et les salaires.", "Les deux périodes relèvent du même régime, puisque la productivité et les salaires augmentent dans les deux cas.", "En période 2, la hausse de la dette des ménages prouve que leurs salaires augmentent plus vite que la productivité."], c: 0,
    pourquoi: [null, "Le tableau montre l’inverse. En période 2, la productivité ralentit de 4,0 % à 1,5 % par an et les salaires réels de 3,8 % à 0,6 %.", "L’école de la régulation ne regarde pas seulement si les grandeurs augmentent, mais comment elles sont liées. Le rapport entre salaires et productivité, les institutions du travail et le rôle de la finance changent d’une période à l’autre.", "Les salaires réels progressent de 0,6 % par an, moins que la productivité (1,5 %). L’endettement compense des salaires qui ne suivent plus."],
    explication: P("En période 1, le salaire réel progresse presque aussi vite que la productivité (3,8 % contre 4,0 %), et la plupart des salariés sont couverts par une convention collective. La consommation de masse absorbe la production de masse. C’est le régime <b>fordiste</b>.", "En période 2, le salaire décroche de la productivité, les conventions reculent, les profits vont davantage aux actionnaires, et la dette des ménages monte. La demande repose sur le crédit et sur la valeur des actifs. Robert Boyer parle d’un régime <b>tiré par la finance</b>, dans le prolongement des travaux de Michel Aglietta sur la financiarisation.", "Pour l’école de la régulation, chaque régime repose sur des institutions cohérentes entre elles, qui finissent par entrer en crise. Elle refuse l’idée d’un capitalisme identique à lui-même dans le temps. On lui reproche de mieux décrire le passé que de prévoir, et de s’appuyer surtout sur les cas français et américain.") },

  { id: "vi3-vf-cycle", theme: "visions", niveau: 3, type: "vf", notion: "cycles",
    titre: "Trois lectures des crises", competence: "Attribuer à chaque théorie des crises la prédiction qui en découle.",
    enonce: P("Indiquez si chaque affirmation est vraie ou fausse."),
    affirmations: [
      ["Pour Mises et Hayek, un taux d’intérêt maintenu sous son niveau naturel pousse les entreprises à lancer des projets trop longs, qui se révèlent ensuite non rentables.", true, "C’est le cœur de la théorie autrichienne du cycle. Le crédit bon marché fait croire à une épargne abondante qui n’existe pas, et l’erreur apparaît quand les taux remontent."],
      ["Pour Keynes, une récession vient d’un excès d’investissement, qu’une hausse des taux d’intérêt doit corriger.", false, "Pour Keynes, la récession vient d’une chute de l’investissement, due à des anticipations dégradées. Il faut le soutenir, par des taux bas et par la dépense publique."],
      ["Pour Minsky comme pour les économistes autrichiens, le bon remède à une crise financière est de laisser les banques en difficulté faire faillite.", false, "Ils s’opposent sur ce point. Minsky défend l’intervention du prêteur en dernier ressort et un budget public important pour arrêter la chute. Les Autrichiens y voient ce qui prépare la crise suivante."],
      ["Pour la théorie autrichienne, une relance par le crédit ou par la dépense publique retarde la liquidation des mauvais investissements et prolonge la crise.", true, "La récession y est une phase d’assainissement. Ce raisonnement a été opposé aux politiques de soutien après 1929 comme après 2008."]
    ] },

  { id: "vi3-red-valeur", theme: "visions", niveau: 3, type: "redaction", notion: "valeur-travail",
    titre: "D’où vient la valeur d’un bien ?", competence: "Comparer les théories de la valeur et ce qu’elles impliquent pour la répartition.",
    enonce: P("Un litre d’eau coûte moins d’un centime, un diamant des milliers de francs. Une heure de travail d’une infirmière est payée bien moins qu’une heure d’un gérant de fonds. Derrière ces écarts se trouve une question ancienne. Qu’est-ce qui fait la valeur d’un bien ?", "<b>Consigne :</b> comparez au moins trois réponses en les rattachant à leurs auteurs (valeur-travail chez Smith, Ricardo et Marx ; utilité marginale chez Jevons, Menger et Walras ; synthèse de Marshall ; critique de Polanyi ou de l’économie féministe sur ce qui n’a pas de prix). Dites pour chacune ce qui détermine la valeur, ce qu’elle explique bien, ce qu’elle explique mal et ce qu’elle implique pour le partage du revenu. Appliquez-les à un même exemple, puis prenez position. Longueur attendue, 20 à 30 lignes."),
    criteres: ["La réponse présente au moins trois théories et nomme leurs auteurs.", "Elle dit pour chacune ce qui détermine la valeur (travail incorporé, utilité de la dernière unité, offre et demande ensemble, institutions).", "Elle indique pour chacune ce qu’elle explique bien et ce qu’elle explique mal.", "Elle précise ce que chacune implique pour le partage du revenu entre salaires et profits.", "Elle applique ces théories à un même exemple et se termine par une prise de position explicite, justifiée par un des arguments présentés."],
    corrige: P("<b>Valeur-travail.</b> Pour Ricardo et Marx, et en partie pour Smith, la valeur d’un bien reproductible dépend du travail nécessaire pour le produire. La théorie explique bien les prix de long terme des biens industriels, qui suivent les coûts. Elle explique mal le prix des biens rares, comme un tableau ou un diamant. Chez Marx, elle fonde une théorie de la répartition. Le profit vient d’un travail non payé, la plus-value.", "<b>Utilité marginale.</b> Pour Jevons, Menger et Walras, vers 1870, la valeur dépend de l’utilité de la dernière unité disponible. L’eau est indispensable mais abondante, sa dernière unité vaut peu. Le diamant est rare. La théorie résout le paradoxe et s’applique à tous les biens. Elle explique mal ce qui n’a pas de demande solvable, comme les besoins de ceux qui n’ont pas de revenu, et laisse de côté les rapports de pouvoir. Elle fait dépendre les revenus de la productivité marginale de chaque facteur, ce qui retire au profit son caractère de prélèvement.", "<b>Marshall.</b> L’offre et la demande agissent ensemble, comme les deux lames d’une paire de ciseaux. À court terme, l’utilité domine, puisque les quantités sont fixes. À long terme, ce sont les coûts de production. La synthèse réconcilie les deux écoles pour l’analyse des prix, mais laisse de côté la question de Marx sur l’origine du profit. Pour le partage du revenu, les salaires et les profits y suivent la productivité des facteurs et les coûts de production.", "<b>Ce qui n’a pas de prix.</b> Pour Polanyi, le travail, la terre et la monnaie ne sont pas produits pour être vendus, et les traiter comme des marchandises est une fiction. L’économie féministe ajoute que le travail domestique crée de la valeur sans avoir de prix. La valeur marchande dépend d’institutions, et pas seulement de la rareté ou du travail. Pour le partage du revenu, cela implique que les salaires et les profits résultent de règles et de rapports de force, que le marché ne suffit pas à justifier.", "<b>Exemple et prise de position possible.</b> L’écart de salaire entre une infirmière et un gérant de fonds ne s’explique pas par les heures travaillées. La valeur-travail y voit surtout le travail de formation incorporé, ce qui explique mal un écart aussi grand. L’utilité marginale y voit la rareté relative de chaque compétence, les institutionnalistes le rapport de force et les règles de chaque branche. Pour expliquer les prix, la synthèse de Marshall reste l’outil le plus utile. Pour juger si un revenu est mérité, elle ne suffit pas, et les critiques institutionnalistes rappellent qu’un prix élevé ne mesure pas l’utilité sociale d’une activité.") },
]);
  /* =========================== FIN DES COMPLÉMENTS =========================== */
})();
